-- MySQL 8 schema for the AI Scientific Literature Evolution Tracker.
CREATE DATABASE IF NOT EXISTS literature_tracker CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE literature_tracker;
CREATE TABLE IF NOT EXISTS users (id BIGINT PRIMARY KEY AUTO_INCREMENT, name VARCHAR(120) NOT NULL, email VARCHAR(255) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, role ENUM('ADMIN','RESEARCHER','USER') NOT NULL DEFAULT 'USER', created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS papers (id BIGINT PRIMARY KEY AUTO_INCREMENT, title VARCHAR(500) NOT NULL, abstract TEXT, year SMALLINT, venue VARCHAR(255), doi VARCHAR(255) UNIQUE, citations INT NOT NULL DEFAULT 0, url VARCHAR(1000), domain VARCHAR(120), created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, INDEX ix_papers_year(year), INDEX ix_papers_domain(domain), FULLTEXT INDEX ft_papers(title,abstract));
CREATE TABLE IF NOT EXISTS authors (id BIGINT PRIMARY KEY AUTO_INCREMENT, name VARCHAR(200) NOT NULL UNIQUE, affiliation VARCHAR(255));
CREATE TABLE IF NOT EXISTS paper_authors (paper_id BIGINT NOT NULL, author_id BIGINT NOT NULL, position SMALLINT NOT NULL DEFAULT 0, PRIMARY KEY(paper_id,author_id), FOREIGN KEY(paper_id) REFERENCES papers(id) ON DELETE CASCADE, FOREIGN KEY(author_id) REFERENCES authors(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS research_topics (id BIGINT PRIMARY KEY AUTO_INCREMENT, name VARCHAR(180) NOT NULL UNIQUE, description TEXT);
CREATE TABLE IF NOT EXISTS paper_topics (paper_id BIGINT NOT NULL, topic_id BIGINT NOT NULL, PRIMARY KEY(paper_id,topic_id), FOREIGN KEY(paper_id) REFERENCES papers(id) ON DELETE CASCADE, FOREIGN KEY(topic_id) REFERENCES research_topics(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS keywords (id BIGINT PRIMARY KEY AUTO_INCREMENT, term VARCHAR(120) NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS paper_keywords (paper_id BIGINT NOT NULL, keyword_id BIGINT NOT NULL, PRIMARY KEY(paper_id,keyword_id), FOREIGN KEY(paper_id) REFERENCES papers(id) ON DELETE CASCADE, FOREIGN KEY(keyword_id) REFERENCES keywords(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS citations (citing_paper_id BIGINT NOT NULL, cited_paper_id BIGINT NOT NULL, PRIMARY KEY(citing_paper_id,cited_paper_id), FOREIGN KEY(citing_paper_id) REFERENCES papers(id) ON DELETE CASCADE, FOREIGN KEY(cited_paper_id) REFERENCES papers(id) ON DELETE CASCADE, CHECK(citing_paper_id <> cited_paper_id));
CREATE TABLE IF NOT EXISTS research_trends (id BIGINT PRIMARY KEY AUTO_INCREMENT, topic_id BIGINT NOT NULL, year SMALLINT NOT NULL, paper_count INT NOT NULL DEFAULT 0, growth_rate DECIMAL(8,2) NOT NULL DEFAULT 0, UNIQUE(topic_id,year), FOREIGN KEY(topic_id) REFERENCES research_topics(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS job_postings (id BIGINT PRIMARY KEY AUTO_INCREMENT, title VARCHAR(255) NOT NULL, company VARCHAR(255), location VARCHAR(180), experience VARCHAR(100), salary VARCHAR(120), skills TEXT, employment_type VARCHAR(80), posting_date VARCHAR(20), is_sample BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS job_skills (id BIGINT PRIMARY KEY AUTO_INCREMENT, name VARCHAR(120) NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS job_posting_skills (job_id BIGINT NOT NULL, skill_id BIGINT NOT NULL, PRIMARY KEY(job_id,skill_id), FOREIGN KEY(job_id) REFERENCES job_postings(id) ON DELETE CASCADE, FOREIGN KEY(skill_id) REFERENCES job_skills(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS chat_history (id BIGINT PRIMARY KEY AUTO_INCREMENT, user_id BIGINT NULL, question TEXT NOT NULL, answer TEXT NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL);
